32	  final String id;
33	  final String content;
34	  final EntrySource source;
35	  final String? chatMessageId;
36	  final String occurredAt;
37	  final int serverRevision;
38	  final String createdAt;
39	  final String updatedAt;
40	
41	  /// Sent/decoded only when non-null (Code Map) —
42	  /// `@JsonKey(includeIfNull: false)` drops the key from `toJson()`
43	  /// entirely rather than serializing an explicit `null`; a response that
44	  /// omits the key likewise decodes to `null` here, `json_serializable`'s
45	  /// default behavior for a nullable field with no `@JsonKey(required:
46	  /// true)`.
47	  @JsonKey(includeIfNull: false)
48	  final int? mediaDurationSeconds;
