60	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
61	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
62	  // `BootSplashScreen`.
63	  static const _skeletonThreshold = Duration(milliseconds: 300);
64	
65	  final ScrollController _scrollController = ScrollController();
66	  Timer? _skeletonTimer;
67	  bool _showSkeleton = false;
68	
69	  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
70	  /// mirroring [_skeletonTimer]/[_showSkeleton] above but keyed off
71	  /// `EntriesSearchCubit`'s `ResourceLoading` rather than
72	  /// `MeusRegistrosLoading`: started fresh on every transition into
73	  /// `ResourceLoading` (`_onSearchStateChanged` below), since unlike the
74	  /// first-load timer above (started once, in [initState]) a search can
75	  /// enter/leave loading many times across one screen visit.
76	  Timer? _searchSkeletonTimer;
77	  bool _showSearchSkeleton = false;
78	
79	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
80	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
81	  /// detail-route instances); cleared once the pushed route is popped, via
82	  /// `whenComplete` below.
83	  bool _navigatingToDetail = false;
84	
85	  @override
86	  void initState() {
87	    super.initState();
88	    widget.cubit.loadFirstPage();
89	    _skeletonTimer = Timer(_skeletonThreshold, () {
90	      if (mounted) {
91	        setState(() => _showSkeleton = true);
92	      }
93	    });
94	    _scrollController.addListener(_onScroll);
95	  }
96	
97	  @override
98	  void dispose() {
99	    _skeletonTimer?.cancel();
100	    _searchSkeletonTimer?.cancel();
101	    _scrollController
102	      ..removeListener(_onScroll)
103	      ..dispose();
104	    super.dispose();
105	  }
106	
107	  /// `BlocConsumer<EntriesSearchCubit, ...>`'s own listener (below) — starts
108	  /// [_searchSkeletonTimer] fresh on every transition into
109	  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
110	  /// but re-armed per search rather than once per screen visit; any other
111	  /// state (including a fast resolve before the 300ms threshold, RNF01)
112	  /// cancels it and resets [_showSearchSkeleton].
113	  void _onSearchStateChanged(
114	    BuildContext context,
115	    Resource<List<Entry>> state,
116	  ) {
117	    _searchSkeletonTimer?.cancel();
118	    if (state is ResourceLoading<List<Entry>>) {
119	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
120	        if (mounted) {
121	          setState(() => _showSearchSkeleton = true);
122	        }
123	      });
124	      return;
125	    }
126	    if (_showSearchSkeleton) {
127	      setState(() => _showSearchSkeleton = false);
128	    }
129	  }
130	
131	  void _openDetail(Entry entry) {
132	    if (_navigatingToDetail) {
133	      return;
134	    }
135	    _navigatingToDetail = true;
136	    context
137	        .push(
138	          '${AppRoutePaths.meusRegistros}/'
139	          '${Uri.encodeComponent(entry.id)}',
140	        )
141	        .whenComplete(() {
142	          if (mounted) {
143	            setState(() => _navigatingToDetail = false);
144	          } else {
145	            _navigatingToDetail = false;
146	          }
147	        });
148	  }
149	
150	  void _onScroll() {
151	    if (!_scrollController.hasClients) {
152	      return;
153	    }
154	    final position = _scrollController.position;
155	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
156	    // purely as a scroll-distance buffer, not a new literal) for a
157	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
158	    // there's no further page or a call is already in flight.
159	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
160	      widget.cubit.loadMore();
161	    }
162	  }
