164	  @override
165	  Widget build(BuildContext context) {
166	    return MultiBlocProvider(
167	      providers: [
168	        BlocProvider.value(value: widget.cubit),
169	        BlocProvider.value(value: widget.searchCubit),
170	      ],
171	      child: Scaffold(
172	        backgroundColor: DesignTokens.colorSurfaceBg,
173	        body: Column(
174	          children: [
175	            const BackArrowHeader(title: 'Meus Registros'),
176	            Padding(
177	              padding: const EdgeInsets.fromLTRB(
178	                DesignTokens.spacingMd,
179	                DesignTokens.spacingMd,
180	                DesignTokens.spacingMd,
181	                0,
182	              ),
183	              child: EntriesSearchBar(onChanged: widget.searchCubit.onQueryChanged),
184	            ),
185	            Expanded(
186	              child: BlocConsumer<EntriesSearchCubit, Resource<List<Entry>>>(
187	                listener: _onSearchStateChanged,
188	                builder: (context, searchState) {
189	                  // Boundaries: "an empty query reverts to the normal
