194	                  if (searchState is ResourceIdle<List<Entry>>) {
195	                    return BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
196	                      builder: (context, state) => switch (state) {
197	                        MeusRegistrosLoading() =>
